CREATE OR REPLACE FUNCTION audit_changes()
RETURNS TRIGGER AS $$
DECLARE
    changed JSONB;
    old_j JSONB;
    new_j JSONB;
BEGIN
    IF TG_OP = 'DELETE' THEN
        INSERT INTO audit_log (
                table_name, record_id,
                operation, old_data,
                changed_by, changed_at
            )
            VALUES (
                TG_TABLE_NAME, OLD.id,
                'DELETE', TO_JSONB(OLD),
                COALESCE(
                    CURRENT_SETTING(
                        'app.current_user',
                        true
                    ), 'system'
                ),
                CURRENT_TIMESTAMP
            );
        RETURN OLD;
    END IF;
    IF TG_OP = 'INSERT' THEN
        INSERT INTO audit_log (
                table_name, record_id,
                operation, new_data,
                changed_by, changed_at
            )
            VALUES (
                TG_TABLE_NAME, NEW.id,
                'INSERT', TO_JSONB(NEW),
                COALESCE(
                    CURRENT_SETTING(
                        'app.current_user',
                        true
                    ), 'system'
                ),
                CURRENT_TIMESTAMP
            );
        RETURN NEW;
    END IF;
    old_j := TO_JSONB(OLD);
    new_j := TO_JSONB(NEW);
    SELECT JSONB_OBJECT_AGG(
            key, value
        )
        INTO changed
        FROM JSONB_EACH(new_j)
        WHERE new_j -> key
            IS DISTINCT FROM
            old_j -> key;
    IF changed IS NOT NULL THEN
        INSERT INTO audit_log (
                table_name, record_id,
                operation, old_data,
                new_data, changed_fields,
                changed_by, changed_at
            )
            VALUES (
                TG_TABLE_NAME, NEW.id,
                'UPDATE', old_j,
                new_j, changed,
                COALESCE(
                    CURRENT_SETTING(
                        'app.current_user',
                        true
                    ), 'system'
                ),
                CURRENT_TIMESTAMP
            );
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_orders_audit
    AFTER INSERT OR UPDATE OR DELETE
    ON orders
    FOR EACH ROW
    EXECUTE FUNCTION audit_changes();
